void Solver::rephase() {
    rephases = 0;
    threshold *= 0.9;
    rephase_limit += 8192;

    // Adaptive phase selection based on recent performance
    int phase_choice = rand() % 100;

    if (phase_choice < 40) {
        // 40%: Use local best phases (exploit)
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    }
    else if (phase_choice < 70) {
        // 30%: Invert local best phases (diversify)
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    }
    else if (phase_choice < 90) {
        // 20%: Random phases (explore)
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    }
    else {
        // 10%: Reset to saved phases from earlier (preserve)
        // No change to saved[] array
    }
}
